 page=f'''{head}<title>{escape(title)} — Susie Kirchgessner</title><meta name="description" content="Sample case study structure for {escape(title.lower())} in Susie Kirchgessner’s portfolio."></head><body>{header}<main class="case-main wrap"><a class="back-link" href="/#work">← All work</a><div class="case-heading"><p class="overline">Sample case study / {escape(cat)}</p><h1>{escape(title)}</h1><p>{escape(heading)}. {escape(desc)}</p></div>{art(p)}<div class="case-notice">Sample structure: this page shows where real project details and evidence will go. It does not claim a completed project or result.</div><div class="case-body">{body}</div><a class="back-link end" href="/#work">← Back to all work</a></main>{footer}</body></html>'''
